 '"fm.group_members:update:why"', '"fm.groups:column id, owner_id:items"', '"fm.groups:column id, owner_id:why"', '"fm.groups:column parent_id after:items"', '"fm.groups:column parent_id after:why"', '"fm.groups:delete:items"', '"fm.groups:delete:why"', '"fm.groups:insert:items"', '"fm.groups:insert:refuse"', '"fm.groups:insert:why"', '"fm.groups:rules:explain"', '"fm.groups:update:items"', '"fm.groups:update:refuse"', '"fm.groups:update:why"']::text[]) LOOP
